INSERT INTO problem_versions (id, problem_id, version_no, status, statement_md, constraints_md, java_template, published_at) VALUES
 (2401, 1401, 1, 'PUBLISHED', '给定一个公历日期，请计算它是这一年的第几天。\n输入格式：一行，一个日期，格式为 `YYYY-MM-DD`，其中月份与日期都写成两位（不足两位补 `0`），例如 `2019-02-28`。\n输出格式：一行，一个十进制整数，表示该日期是这一年的第几天（1 月 1 日记为第 1 天）。', '- `1 <= 年份 <= 9999`\n- 输入的日期保证合法（月份在 1 到 12 之间，日期不超过该月的天数）\n- 闰年指能被 4 整除但不能被 100 整除，或者能被 400 整除的年份', 'import java.io.*;\n\npublic class Main {\n    public static void main(String[] args) throws Exception {\n        // 从 stdin 读取输入，把答案打印到 stdout\n    }\n}\n', CURRENT_TIMESTAMP),
 (2402, 1402, 1, 'PUBLISHED', '给定两个年份 `a` 和 `b`，请统计区间 `[a, b]` 中闰年的个数。闰年指能被 `4` 整除但不能被 `100` 整除，或者能被 `400` 整除的年份。\n输入格式：一行，两个整数 `a` 与 `b`，两者之间用单个 `;` 分隔，例如 `2000;2010`。\n输出格式：一行，一个十进制整数，表示 `[a, b]` 中闰年的个数。', '- `1 <= a <= b <= 10^9`', 'import java.io.*;\n\npublic class Main {\n    public static void main(String[] args) throws Exception {\n        // 从 stdin 读取输入，把答案打印到 stdout\n    }\n}\n', CURRENT_TIMESTAMP),
 (2403, 1403, 1, 'PUBLISHED', '给定一个非负整数 `n`，请输出它的二进制表示。\n输入格式：一行，一个非负整数 `n`，例如 `13`。\n输出格式：一行，`n` 的二进制表示，不能有前导零；`n = 0` 时输出 `0`。', '- `0 <= n <= 2^63 - 1`', 'import java.io.*;\n\npublic class Main {\n    public static void main(String[] args) throws Exception {\n        // 从 stdin 读取输入，把答案打印到 stdout\n    }\n}\n', CURRENT_TIMESTAMP),
 (2404, 1404, 1, 'PUBLISHED', '给定一个正整数 `n`，请判断它的二进制表示（不含前导零）是否为回文串。回文串指从左到右读和从右到左读完全相同的字符串。\n输入格式：一行，一个正整数 `n`，例如 `9`。\n输出格式：一行，若 `n` 的二进制表示是回文串则输出 `true`，否则输出 `false`（全小写）。', '- `1 <= n <= 2^63 - 1`', 'import java.io.*;\n\npublic class Main {\n    public static void main(String[] args) throws Exception {\n        // 从 stdin 读取输入，把答案打印到 stdout\n    }\n}\n', CURRENT_TIMESTAMP),
 (2405, 1405, 1, 'PUBLISHED', '水仙花数是指各位数字的立方和恰好等于它本身的三位数，例如 `153 = 1^3 + 5^3 + 3^3`。\n给定区间 `[m, n]`，请按从小到大的顺序输出区间内所有的水仙花数。\n输入格式：一行，两个三位整数 `m` 与 `n`，两者之间用单个 `;` 分隔，例如 `100;400`。\n输出格式：一行，区间内所有的水仙花数按从小到大的顺序构成一个数组，写成 `[153,370]` 形式（元素之间无空格）；若区间内没有水仙花数，输出 `[]`。', '- `100 <= m <= n <= 999`', 'import java.io.*;\n\npublic class Main {\n    public static void main(String[] args) throws Exception {\n        // 从 stdin 读取输入，把答案打印到 stdout\n    }\n}\n', CURRENT_TIMESTAMP),
 (2406, 1406, 1, 'PUBLISHED', '完全数是指所有真因数（小于它本身的正因数）之和恰好等于它本身的正整数，例如 `28 = 1 + 2 + 4 + 7 + 14`。\n给定一个正整数 `n`，请判断它是否为完全数。\n输入格式：一行，一个正整数 `n`，例如 `28`。\n输出格式：一行，若 `n` 是完全数则输出 `true`，否则输出 `false`（全小写）。', '- `1 <= n <= 10^8`', 'import java.io.*;\n\npublic class Main {\n    public static void main(String[] args) throws Exception {\n        // 从 stdin 读取输入，把答案打印到 stdout\n    }\n}\n', CURRENT_TIMESTAMP),
 (2407, 1407, 1, 'PUBLISHED', '给定一个正整数 `n`，请输出它的正因数个数。\n输入格式：一行，一个正整数 `n`，例如 `12`。\n输出格式：一行，一个十进制整数，表示 `n` 的正因数个数。', '- `1 <= n <= 10^9`', 'import java.io.*;\n\npublic class Main {\n    public static void main(String[] args) throws Exception {\n        // 从 stdin 读取输入，把答案打印到 stdout\n    }\n}\n', CURRENT_TIMESTAMP),
 (2408, 1408, 1, 'PUBLISHED', '一个机器人初始位于平面直角坐标系的 `(0, 0)` 处。给定一串移动指令，机器人按顺序执行：`U` 表示 `y` 坐标加 1，`D` 表示 `y` 坐标减 1，`L` 表示 `x` 坐标减 1，`R` 表示 `x` 坐标加 1。\n请统计机器人经过的不同位置（含起点）的数量。\n输入格式：一行，一个只由 `U`、`D`、`L`、`R` 组成的字符串，长度不超过 10^5，例如 `UD`。\n输出格式：一行，一个十进制整数，表示机器人经过的不同位置的数量。', '- `1 <= 字符串长度 <= 10^5`\n- 字符串只包含 `U`、`D`、`L`、`R`', 'import java.io.*;\n\npublic class Main {\n    public static void main(String[] args) throws Exception {\n        // 从 stdin 读取输入，把答案打印到 stdout\n    }\n}\n', CURRENT_TIMESTAMP),
 (2409, 1409, 1, 'PUBLISHED', '两名玩家玩「石头剪刀布」，各自给出一个等长的出拳序列，序列中只含 `R`（石头）、`P`（布）、`S`（剪刀），两个序列逐位对应每一局。规则为 `R` 胜 `S`、`S` 胜 `P`、`P` 胜 `R`，出拳相同时为平局。\n请计算第一名玩家的净胜局数，即（他胜的局数）减去（他负的局数）。\n输入格式：一行，两个等长字符串，两者之间用单个 `;` 分隔，例如 `RRR;SSS`。\n输出格式：一行，一个十进制整数，表示第一名玩家的净胜局数，可能为负数。', '- `1 <= 每个字符串的长度 <= 10^5`\n- 两个字符串长度相同，且只包含 `R`、`P`、`S`', 'import java.io.*;\n\npublic class Main {\n    public static void main(String[] args) throws Exception {\n        // 从 stdin 读取输入，把答案打印到 stdout\n    }\n}\n', CURRENT_TIMESTAMP),
 (2410, 1410, 1, 'PUBLISHED', '给定一个只含小写英文字母的字符串，请统计其中元音字母 `a`、`e`、`i`、`o`、`u` 出现的总次数。\n输入格式：一行，一个只含小写英文字母的字符串，长度不超过 10^5，例如 `hello`。\n输出格式：一行，一个十进制整数，表示元音字母的个数。', '- `1 <= 字符串长度 <= 10^5`\n- 字符串只包含小写英文字母', 'import java.io.*;\n\npublic class Main {\n    public static void main(String[] args) throws Exception {\n        // 从 stdin 读取输入，把答案打印到 stdout\n    }\n}\n', CURRENT_TIMESTAMP),
 (2411, 1411, 1, 'PUBLISHED', '已知 `1900-01-01` 是星期一。给定一个日期，请判断它是星期几。\n输入格式：一行，一个日期，格式为 `YYYY-MM-DD`，其中月份与日期都写成两位（不足两位补 `0`），例如 `2021-01-01`。\n输出格式：一行，一个十进制整数，取值 `1` 到 `7`，`1` 表示星期一、`2` 表示星期二、……、`7` 表示星期日。', '- 日期范围：`1900-01-01` 到 `2099-12-31`\n- 输入的日期保证合法（月份在 1 到 12 之间，日期不超过该月的天数）', 'import java.io.*;\n\npublic class Main {\n    public static void main(String[] args) throws Exception {\n        // 从 stdin 读取输入，把答案打印到 stdout\n    }\n}\n', CURRENT_TIMESTAMP),
 (2412, 1412, 1, 'PUBLISHED', '给定一个日期和一个非负整数 `k`，请计算该日期之后第 `k` 天的日期（`k = 0` 表示日期本身）。\n输入格式：一行，一个日期与一个整数 `k`，两者之间用单个 `;` 分隔；日期格式为 `YYYY-MM-DD`，其中月份与日期都写成两位（不足两位补 `0`），例如 `2020-02-28;3`。\n输出格式：一行，结果日期，格式为 `YYYY-MM-DD`（年份补足四位，月份与日期补足两位）。', '- 起始日期不早于 `1900-01-01`\n- `0 <= k <= 10^4`\n- 保证结果日期不晚于 `2099-12-31`', 'import java.io.*;\n\npublic class Main {\n    public static void main(String[] args) throws Exception {\n        // 从 stdin 读取输入，把答案打印到 stdout\n    }\n}\n', CURRENT_TIMESTAMP),
 (2413, 1413, 1, 'PUBLISHED', '给定两个日期，请计算它们之间相差的天数（取绝对值）。\n输入格式：一行，两个日期，两者之间用单个 `;` 分隔；每个日期的格式为 `YYYY-MM-DD`，其中月份与日期都写成两位（不足两位补 `0`），例如 `2020-01-01;2020-03-01`。\n输出格式：一行，一个十进制整数，表示两个日期相差的天数，结果非负。', '- 两个日期都在 `1900-01-01` 到 `2099-12-31` 之间\n- 输入的日期保证合法（月份在 1 到 12 之间，日期不超过该月的天数）', 'import java.io.*;\n\npublic class Main {\n    public static void main(String[] args) throws Exception {\n        // 从 stdin 读取输入，把答案打印到 stdout\n    }\n}\n', CURRENT_TIMESTAMP),
 (2414, 1414, 1, 'PUBLISHED', '给定一个非负整数 `n` 和一个进制 `b`，请输出 `n` 在 `b` 进制下的表示。大于 9 的数字位依次用大写字母 `A` 到 `Z` 表示，即 `A` 表示 10，`B` 表示 11，……，`Z` 表示 35。\n输入格式：一行，整数 `n` 与进制 `b`，两者之间用单个 `;` 分隔，例如 `255;16`。\n输出格式：一行，`n` 在 `b` 进制下的表示，不能有前导零；`n = 0` 时输出 `0`。', '- `0 <= n <= 10^18`\n- `2 <= b <= 36`', 'import java.io.*;\n\npublic class Main {\n    public static void main(String[] args) throws Exception {\n        // 从 stdin 读取输入，把答案打印到 stdout\n    }\n}\n', CURRENT_TIMESTAMP),
 (2415, 1415, 1, 'PUBLISHED', '给定两个整数 `a` 和 `b`，请统计区间 `[a, b]` 中素数的个数。素数指大于 1 且只有 1 和它本身两个正因数的整数。\n输入格式：一行，两个整数 `a` 与 `b`，两者之间用单个 `;` 分隔，例如 `1;10`。\n输出格式：一行，一个十进制整数，表示 `[a, b]` 中素数的个数。', '- `1 <= a <= b <= 10^6`', 'import java.io.*;\n\npublic class Main {\n    public static void main(String[] args) throws Exception {\n        // 从 stdin 读取输入，把答案打印到 stdout\n    }\n}\n', CURRENT_TIMESTAMP),
 (2416, 1416, 1, 'PUBLISHED', '给定一个正整数 `n`，请统计满足下列条件的三元组 `(a, b, c)` 的个数：`a`、`b`、`c` 都是正整数，`a <= b <= c`，`a + b + c = n`，且 `a^2 + b^2 = c^2`。\n输入格式：一行，一个正整数 `n`，例如 `12`。\n输出格式：一行，一个十进制整数，表示满足条件的三元组个数。', '- `3 <= n <= 10^4`', 'import java.io.*;\n\npublic class Main {\n    public static void main(String[] args) throws Exception {\n        // 从 stdin 读取输入，把答案打印到 stdout\n    }\n}\n', CURRENT_TIMESTAMP),
 (2417, 1417, 1, 'PUBLISHED', '`n` 个人围成一圈，编号从 `1` 到 `n`。从 `1` 号开始报数，报到 `k` 的人离开圈子，然后从离开者的下一位重新从 `1` 开始报数，如此重复，直到圈中只剩一个人。\n请输出最后留下的人的编号。\n输入格式：一行，整数 `n` 与 `k`，两者之间用单个 `;` 分隔，例如 `10;3`。\n输出格式：一行，一个十进制整数，表示最后留下的人的编号（编号从 `1` 开始）。', '- `1 <= n <= 10^6`\n- `1 <= k <= 10^6`', 'import java.io.*;\n\npublic class Main {\n    public static void main(String[] args) throws Exception {\n        // 从 stdin 读取输入，把答案打印到 stdout\n    }\n}\n', CURRENT_TIMESTAMP),
 (2418, 1418, 1, 'PUBLISHED', '有 `n` 盏灯，编号从 `1` 到 `n`，初始全部熄灭。接下来依次执行 `n` 轮操作：第 `i` 轮把所有编号为 `i` 的倍数的灯翻转一次（亮变灭，灭变亮）。\n请输出 `n` 轮操作结束后仍然亮着的灯的数量。\n输入格式：一行，一个正整数 `n`，例如 `10`。\n输出格式：一行，一个十进制整数，表示最后亮着的灯的数量。', '- `1 <= n <= 10^9`', 'import java.io.*;\n\npublic class Main {\n    public static void main(String[] args) throws Exception {\n        // 从 stdin 读取输入，把答案打印到 stdout\n    }\n}\n', CURRENT_TIMESTAMP),
 (2419, 1419, 1, 'PUBLISHED', '给定一个正整数 `n`，请计算 `1` 到 `n` 之间（含 `1` 和 `n`）所有能被 `3` 整除或能被 `5` 整除的整数之和，同一个整数只计一次。\n输入格式：一行，一个正整数 `n`，例如 `10`。\n输出格式：一行，一个十进制整数，表示满足条件的整数之和。', '- `1 <= n <= 10^9`', 'import java.io.*;\n\npublic class Main {\n    public static void main(String[] args) throws Exception {\n        // 从 stdin 读取输入，把答案打印到 stdout\n    }\n}\n', CURRENT_TIMESTAMP),
 (2420, 1420, 1, 'PUBLISHED', '给定一个正整数 `n` 和一个数字 `d`（`0` 到 `9`），请统计从 `1` 到 `n` 的所有整数的十进制写法中，数字 `d` 一共出现了多少次，不计算前导零。例如在 `1` 到 `13` 中，数字 `1` 出现了 6 次。\n输入格式：一行，整数 `n` 与数字 `d`，两者之间用单个 `;` 分隔，例如 `20;1`。\n输出格式：一行，一个十进制整数，表示数字 `d` 出现的总次数。', '- `1 <= n <= 10^18`\n- `0 <= d <= 9`', 'import java.io.*;\n\npublic class Main {\n    public static void main(String[] args) throws Exception {\n        // 从 stdin 读取输入，把答案打印到 stdout\n    }\n}\n', CURRENT_TIMESTAMP),
 (2421, 1421, 1, 'PUBLISHED', '把一个只由 0 和 1 组成的字符串当作二进制数，输出它对应的十进制值。字符串可能有前导零。\n输入格式：一行，一个长度不超过 62 的二进制字符串（只含 `0` 和 `1`，不含空格）。\n输出格式：一行，一个十进制整数。', '- `1 <= 字符串长度 <= 62`\n- 允许前导零（例如 `000101` 表示 5）\n- 结果不超过 64 位有符号整数范围', 'import java.io.*;\n\npublic class Main {\n    public static void main(String[] args) throws Exception {\n        // 从 stdin 读取输入，把答案打印到 stdout\n    }\n}\n', CURRENT_TIMESTAMP),
 (2422, 1422, 1, 'PUBLISHED', '行程编码（RLE）把连续重复的字符替换成「字符 + 重复次数」。请对给定字符串做行程编码。\n输入格式：一行，一个只含小写字母且不含空格的字符串，长度不超过 10^5。\n输出格式：一行，编码结果：对每一段连续相同的字符，依次输出该字符和它的重复次数（次数写成十进制，即使是 1 也要写出来）。例如 `aaabbc` 输出 `a3b2c1`。', '- `1 <= 字符串长度 <= 10^5`\n- 只含小写字母 `a`-`z`\n- 次数可能是多位数（如连续 100 个相同字符要输出 `100`）', 'import java.io.*;\n\npublic class Main {\n    public static void main(String[] args) throws Exception {\n        // 从 stdin 读取输入，把答案打印到 stdout\n    }\n}\n', CURRENT_TIMESTAMP),
 (2423, 1423, 1, 'PUBLISHED', '给定一个时刻（小时与分钟），求时针与分针之间较小的那个夹角，结果用「度」表示。\n输入格式：一行，形如 `3;30`，分号前是小时 `h`（`0 <= h <= 23`），分号后是分钟 `m`（`0 <= m <= 59`）。24 小时制下，时针位置按 12 小时刻度循环（例如 15 点与 3 点相同）。\n输出格式：一行，一个整数，表示两针较小夹角的角度（0 到 180 之间）。因为夹角一定是 0.5 度的整数倍，结果必为整数。', '- `0 <= h <= 23`、`0 <= m <= 59`\n- 时针每分钟走 0.5 度，分针每分钟走 6 度\n- 输出 0..180 之间的整数（较大夹角要换算成 360 减它）', 'import java.io.*;\n\npublic class Main {\n    public static void main(String[] args) throws Exception {\n        // 从 stdin 读取输入，把答案打印到 stdout\n    }\n}\n', CURRENT_TIMESTAMP);
